// AUTH
app.get('/api/v1/auth/google/start', authLimiter, async (req, res) => { try { const state = random(); const verifier = random(); const redirectTo = `${origin}/api/v1/auth/google/callback`; const authorize = new URL(`${env.SUPABASE_URL}/auth/v1/authorize`); authorize.searchParams.set('provider', 'google'); authorize.searchParams.set('redirect_to', redirectTo); authorize.searchParams.set('code_challenge', pkceChallenge(verifier)); authorize.searchParams.set('code_challenge_method', 'S256'); authorize.searchParams.set('access_type', 'offline'); authorize.searchParams.set('prompt', 'consent'); await database().from('oauth_states').insert({ id_hash: sha(state), verifier, expires_at: new Date(Date.now() + 600000).toISOString() }); res.set('Set-Cookie', `noeul_oauth=${encodeURIComponent(state)}; Path=/; Max-Age=600; HttpOnly; SameSite=Lax${production ? '; Secure' : ''}`); res.redirect(authorize.toString()); } catch (e) { console.error('google start failed', e); error(res, 503, 'AUTH_NOT_CONFIGURED'); } });

app.get('/api/v1/auth/google/callback', authLimiter, async (req, res) => { try { console.log('[callback] start', { code: req.query.code?.slice(0,10), hasCookie: !!req.headers.cookie, cookieHeader: req.headers.cookie?.slice(0,200) }); const cookies = parseCookies(req.headers.cookie); console.log('[callback] parsed cookies', Object.keys(cookies)); const state = cookies.noeul_oauth; console.log('[callback] state value', state?.slice(0,20)); if (!state || !req.query.code) { console.log('[callback] INVALID_CALLBACK'); return error(res, 400, 'INVALID_CALLBACK'); } const stateHash = sha(state); console.log('[callback] stateHash', stateHash); const { data: row, error: stateErr } = await database().from('oauth_states').delete().eq('id_hash', stateHash).gt('expires_at', new Date().toISOString()).select('verifier').maybeSingle(); console.log('[callback] oauth_states query', { row: !!row, stateErr, expiresCheck: new Date().toISOString() }); if (!row) { console.log('[callback] OAUTH_STATE_EXPIRED - no row found'); return error(res, 400, 'OAUTH_STATE_EXPIRED'); } console.log('[callback] row found', { hasVerifier: !!row.verifier }); const tokenRes = await fetch(`${env.SUPABASE_URL}/auth/v1/token?grant_type=pkce`, { method: 'POST', headers: { apikey: env.SUPABASE_PUBLISHABLE_KEY, 'Content-Type': 'application/json' }, body: JSON.stringify({ auth_code: req.query.code, code_verifier: row.verifier }) }); console.log('[callback] token exchange', { ok: tokenRes.ok, status: tokenRes.status }); const token = await tokenRes.json(); if (!tokenRes.ok || !token.access_token || !token.user) { console.log('[callback] GOOGLE_IDENTITY_REQUIRED', { token }); return error(res, 401, 'GOOGLE_IDENTITY_REQUIRED'); } console.log('[callback] token ok', { userId: token.user.id }); const id = random(); const csrf = random(); await database().from('profiles').upsert({ id: token.user.id, email: token.user.email, name: token.user.user_metadata?.full_name || '' }); console.log('[callback] profile upsert ok'); await database().from('sessions').insert({ id_hash: sha(id), user_id: token.user.id, encrypted_tokens: encryptSessionTokens(token), csrf, aal: token.user?.aal === 'aal2' ? 'aal2' : 'aal1', refreshed_at: new Date().toISOString(), expires_at: new Date(Date.now() + 24*60*60*1000).toISOString() }); console.log('[callback] session insert ok'); setCookie(res, cookieName, id); res.append('Set-Cookie', 'noeul_oauth=; Path=/; Max-Age=0; HttpOnly; SameSite=Lax; Secure'); console.log('[callback] Set-Cookie headers:', res.getHeaders()['set-cookie']); console.log('[callback] 302 redirect to /account'); res.redirect('/account'); } catch (e) { console.error('[callback] error', e); error(res, 503, 'AUTH_CALLBACK_FAILED'); } });

