// USER COUPONS
app.get('/api/v1/me/coupons', authenticate, async (req, res) => { try { const s = req.locals.session; const { data, error: e } = await database().from('user_coupons').select('*,coupons(*)').eq('user_id', s.user_id).eq('status', 'active').order('claimed_at', { ascending: false }); if (e) throw e; const now = new Date().toISOString(); const coupons = (data || []).filter(uc => { const c = uc.coupons; return c && c.starts_at <= now && c.ends_at >= now && (c.used + (c.reserved || 0)) < c.limit_count; }).map(uc => ({ id: uc.id, code: uc.coupon_code, claimed_at: uc.claimed_at, ...uc.coupons })); res.json({ success: true, data: coupons }); } catch { error(res, 503, 'COUPONS_UNAVAILABLE'); } });
app.post('/api/v1/me/coupons', authenticate, async (req, res) => { try { const s = req.locals.session; const code = String(req.body?.code || '').toUpperCase().trim(); if (!code) return error(res, 400, 'COUPON_CODE_REQUIRED'); const { data: coupon } = await database().from('coupons').select('*').eq('code', code).maybeSingle(); if (!coupon) return error(res, 404, 'COUPON_NOT_FOUND'); const now = new Date().toISOString(); if (coupon.starts_at > now || coupon.ends_at < now) return error(res, 400, 'COUPON_EXPIRED'); if ((coupon.used + (coupon.reserved || 0)) >= coupon.limit_count) return error(res, 400, 'COUPON_LIMIT_REACHED'); const { data: existing } = await database().from('user_coupons').select('id').eq('user_id', s.user_id).eq('coupon_code', code).maybeSingle(); if (existing) return error(res, 409, 'COUPON_ALREADY_CLAIMED'); const { data, error: e } = await database().from('user_coupons').insert({ user_id: s.user_id, coupon_code: code, status: 'active' }).select().maybeSingle(); if (e || !data) throw e || new Error('CLAIM_FAILED'); res.status(201).json({ success: true, data: { ...data, ...coupon } }); } catch { error(res, 503, 'COUPONS_UNAVAILABLE'); } });

