app.get('/api/v1/catalog/products', async (req, res) => { try { let q = database().from('products').select('*,categories(slug),product_variants(*),product_media(*)').eq('is_active', true).order('created_at', { ascending: false }); if (req.query.search) { const term = String(req.query.search).replace(/[%_,]/g, c => `\\${c}`).replace(/,/g, '').slice(0, 80).trim(); if (term) q = q.or(`name_ko.ilike.%${term}%,name_en.ilike.%${term}%`); } if (req.query.category) {
      const cat = String(req.query.category).toLowerCase();
      let slugs = [cat];
      if (cat === 'outerwear') slugs = ['jackets'];
      else if (cat === 'tops') slugs = ['tshirts','hoodies'];
      const { data: catRows } = await database().from('categories').select('id').in('slug', slugs);
      if (!catRows || catRows.length === 0) { res.json({ success: true, data: [], total: 0 }); return; }
      q = q.in('category_id', catRows.map(r=>r.id));
    } if (req.query.gender) q = q.in('gender', [req.query.gender, 'unisex']); if (req.query.is_new === 'true' || req.query.is_new === '1' || req.query.isNew === 'true') q = q.eq('is_new', true); if (req.query.is_best === 'true' || req.query.is_best === '1' || req.query.isBest === 'true') q = q.eq('is_best', true); if (req.query.is_sale === 'true' || req.query.is_sale === '1' || req.query.sale === 'true' || req.query.isSale === 'true') q = q.not('discount_price', 'is', null); if (req.query.sort === 'price_asc') q = q.order('price', { ascending: true }); else if (req.query.sort === 'price_desc') q = q.order('price', { ascending: false }); else if (req.query.sort === 'popular' || req.query.sort === 'best') q = q.order('is_best', { ascending: false }); const limit = Math.min(Number(req.query.limit || 24), 100); const offset = Number(req.query.offset || 0); const { data, error: e } = await q.range(offset, offset + limit - 1); if (e) throw e; res.json({ success: true, data: (data || []).map(normalizeProduct), total: (data || []).length }); } catch { error(res, 503, 'CATALOG_UNAVAILABLE'); } });

app.get('/api/v1/catalog/products/:id', async (req, res) => { try { const raw = String(req.params.id || '').trim(); const isNumeric = /^\\d+$/.test(raw); let q = database().from('products').select('*,categories(slug),product_variants(*),product_media(*)').eq('is_active', true); if (isNumeric) q = q.eq('id', Number(raw)); else q = q.eq('slug', raw); const { data, error: e } = await q.maybeSingle(); if (e || !data) return error(res, 404, 'PRODUCT_NOT_FOUND'); const rel = data ? await database().from('products').select('*,categories(slug),product_variants(*),product_media(*)').eq('is_active', true).eq('category_id', data.category_id).neq('id', data.id).order('created_at', { ascending: false }).limit(4) : { data: [] }; res.json({ success: true, data: normalizeProduct(data), related: (rel.data || []).map(normalizeProduct) }); } catch { error(res, 503, 'CATALOG_UNAVAILABLE'); } });
app.get('/api/v1/catalog/categories', async (req, res) => { try { const { data, error: e } = await database().from('categories').select('*').eq('is_active', true).order('sort_order'); if (e) return error(res, 503, 'CATALOG_UNAVAILABLE'); res.json({ success: true, data }); } catch { error(res, 503, 'CATALOG_UNAVAILABLE'); } });
