// ORDERS
function couponDiscountForSubtotal(subtotal, coupon) { if (!coupon) return 0; const today = new Date().toISOString(); if (coupon.starts_at > today || coupon.ends_at < today) return 0; if ((coupon.used + (coupon.reserved || 0)) >= coupon.limit_count) return 0; if (subtotal < (coupon.minimum || 0)) return 0; return Math.min(subtotal, coupon.amount || 0); }
app.post('/api/v1/checkout/quote', authenticate, async (req, res) => { try { const { items, coupon_code } = req.body; const invalid = validateOrderLines(items); if (invalid) return error(res, 400, invalid); const demand = aggregateDemand(items); const ids = [...demand.keys()]; const { data: variants } = await database().from('product_variants').select('*,products(*)').in('id', ids); if (!variants || variants.length !== ids.length) return error(res, 404, 'VARIANT_UNAVAILABLE'); let subtotal = 0; const lines = []; for (const [variantId, totalQty] of demand) { const v = variants.find(x => x.id === variantId); if (!v || !v.active) return error(res, 400, 'VARIANT_UNAVAILABLE'); if ((v.stock || 0) - (v.reserved || 0) < totalQty) return error(res, 409, 'INSUFFICIENT_STOCK'); } for (const item of items) { const v = variants.find(x => x.id === item.variant_id); const base = v.products || {}; const unit = Math.max(1, (base.discount_price || base.price || 0) + (v.price_delta || 0)); subtotal += unit * item.quantity; lines.push({ variant_id: v.id, quantity: item.quantity, unit_price: unit }); } let discount = 0; if (coupon_code) { const { data: coupon } = await database().from('coupons').select('*').eq('code', String(coupon_code).toUpperCase().trim()).maybeSingle(); const todayIso = new Date().toISOString(); if (coupon && (coupon.starts_at || '') <= todayIso && (coupon.ends_at || '') >= todayIso && ((coupon.used || 0) + (coupon.reserved || 0)) < coupon.limit_count && subtotal >= (coupon.minimum || 0)) { discount = Math.min(subtotal, coupon.amount || 0); } } const shipCfg = await getShippingConfig(); const shippingFee = subtotal - discount >= shipCfg.threshold ? 0 : shipCfg.fee; const quoted = subtotal - discount + shippingFee; if (quoted < 1) return error(res, 400, 'MINIMUM_AMOUNT'); res.json({ success: true, data: { subtotal, discount, shipping: shippingFee, amount: quoted, items: lines, coupon: discount > 0 ? 'applied' : null } }); } catch { error(res, 503, 'QUOTE_UNAVAILABLE'); } });

app.post('/api/v1/orders', authenticate, checkoutLimiter, async (req, res) => { try { const s = req.locals.session; const idempotencyKey = String(req.get('Idempotency-Key') || ''); if (!/^[A-Za-z0-9._:-]{8,200}$/.test(idempotencyKey)) return error(res, 400, 'IDEMPOTENCY_KEY_REQUIRED'); const { items, coupon_code, address } = req.body || {}; const invalid = validateOrderLines(items); if (invalid) return error(res, 400, invalid); /* Idempotency: same key + same body returns the stored order; same key + different body is a conflict (finding #11). */ const requestHash = createHash('sha256').update(JSON.stringify({ items, coupon_code: coupon_code || null, address: address || null })).digest('hex'); const { data: existing } = await database().from('orders').select('*').eq('user_id', s.user_id).eq('idempotency_key', idempotencyKey).maybeSingle(); if (existing) { if (existing.request_hash === requestHash) return res.json({ success: true, data: existing, duplicated: true }); return error(res, 409, 'IDEMPOTENCY_KEY_REUSE'); } /* Authoritative pricing (finding: never trust client totals). Recompute from variants/coupons/settings exactly like the quote endpoint. */ const demand = aggregateDemand(items); const ids = [...demand.keys()]; const { data: variants } = await database().from('product_variants').select('*,products(*)').in('id', ids); if (!variants || variants.length !== ids.length) return error(res, 404, 'VARIANT_UNAVAILABLE'); let subtotal = 0; const lines = []; for (const [variantId, totalQty] of demand) { const v = variants.find(x => x.id === variantId); if (!v || !v.active) return error(res, 400, 'VARIANT_UNAVAILABLE'); if ((v.stock || 0) - (v.reserved || 0) < totalQty) return error(res, 409, 'INSUFFICIENT_STOCK'); } for (const item of items) { const v = variants.find(x => x.id === item.variant_id); const base = v.products || {}; const unit = Math.max(1, (base.discount_price || base.price || 0) + (v.price_delta || 0)); subtotal += unit * item.quantity; lines.push({ variant_id: v.id, quantity: item.quantity, unit_price: unit, snapshot: { sku: v.sku, color: v.color, size: v.size } }); } let discount = 0; let couponCode = null; if (coupon_code) { const { data: coupon } = await database().from('coupons').select('*').eq('code', String(coupon_code).toUpperCase().trim()).maybeSingle(); const today = new Date().toISOString(); if (coupon && coupon.starts_at <= today && coupon.ends_at >= today && (coupon.used + (coupon.reserved || 0)) < coupon.limit_count && subtotal >= (coupon.minimum || 0)) { discount = Math.min(subtotal, coupon.amount || 0); couponCode = coupon.code; } } const shipCfg = await getShippingConfig(); const shippingFee = subtotal - discount >= shipCfg.threshold ? 0 : shipCfg.fee; const amount = subtotal - discount + shippingFee; if (amount < 1) return error(res, 400, 'MINIMUM_AMOUNT'); const number = `NE${Date.now().toString(36).toUpperCase()}${random().slice(2, 8).toUpperCase()}`; /* tryPlaceOrderRpc: rpc('place_order') before JS fallback. Falls back to create + outbox for COUPON_INVALID */ /* Create the order, then reserve stock + write items + outbox. On any later failure, compensate by releasing reservations and removing the order so no partial/duplicate order survives (finding #11). */ const { data: order, error: oErr } = await database().from('orders').insert({ user_id: s.user_id, order_number: number, subtotal, discount, shipping: shippingFee, amount, coupon_code: couponCode, address: address || {}, status: 'pending_payment', idempotency_key: idempotencyKey, request_hash: requestHash }).select().maybeSingle(); if (oErr || !order) throw oErr || new Error('ORDER_CREATE_FAILED'); try { for (const [variantId, totalQty] of demand) { const { data: current } = await database().from('product_variants').select('stock,reserved').eq('id', variantId).maybeSingle(); if (!current || (current.stock || 0) - (current.reserved || 0) < totalQty) throw Object.assign(new Error('INSUFFICIENT_STOCK'), { status: 409 }); await database().from('product_variants').update({ reserved: (current.reserved || 0) + totalQty }).eq('id', variantId); } if (couponCode) { const { data: cRow } = await database().from('coupons').select('reserved').eq('code', couponCode).maybeSingle(); await database().from('coupons').update({ reserved: (cRow?.reserved || 0) + 1 }).eq('code', couponCode); } const grouped = new Map(); for (const l of lines) { const g = grouped.get(l.variant_id) || { variant_id: l.variant_id, quantity: 0, unit_price: l.unit_price, snapshot: l.snapshot || {} }; g.quantity += l.quantity; grouped.set(l.variant_id, g); } await database().from('order_items').insert([...grouped.values()].map(l => ({ order_id: order.id, variant_id: l.variant_id, quantity: l.quantity, unit_price: l.unit_price, snapshot: l.snapshot || {} }))); await database().from('outbox').insert({ effect_key: `order:${order.id}`, kind: 'ORDER_CREATED', payload: { order_id: order.id } }); } catch (stepErr) { try { for (const [variantId, totalQty] of demand) { const { data: cur } = await database().from('product_variants').select('reserved').eq('id', variantId).maybeSingle(); if (cur && (cur.reserved || 0) >= totalQty) await database().from('product_variants').update({ reserved: cur.reserved - totalQty }).eq('id', variantId); } await database().from('orders').delete().eq('id', order.id); } catch { /* compensation best-effort */ } if (stepErr && stepErr.message === 'INSUFFICIENT_STOCK') return error(res, 409, 'INSUFFICIENT_STOCK'); throw stepErr; } res.status(201).json({ success: true, data: order }); } catch { error(res, 503, 'ORDER_UNAVAILABLE'); } });
app.get('/api/v1/orders', authenticate, async (req, res) => { try { const { data, error: e } = await database().from('orders').select('*').eq('user_id', req.locals.session.user_id).order('created_at', { ascending: false }).limit(100); if (e) throw e; res.json({ success: true, data: data || [] }); } catch { error(res, 503, 'ORDERS_UNAVAILABLE'); } });
app.get('/api/v1/orders/:publicId', authenticate, async (req, res) => { try { const { data: order } = await database().from('orders').select('*').eq('order_number', req.params.publicId).eq('user_id', req.locals.session.user_id).maybeSingle(); if (!order) return error(res, 404, 'ORDER_NOT_FOUND'); const items = await database().from('order_items').select('*').eq('order_id', order.id); res.json({ success: true, data: { ...order, items } }); } catch { error(res, 503, 'ORDERS_UNAVAILABLE'); } });

// Cancel order (finding #21): idempotent release of stock reservations and
// coupon holds. Only unsettled orders can cancel; already-canceled orders
// return success without double-releasing.
app.post('/api/v1/orders/:publicId/cancel', authenticate, async (req, res) => { try { const s = req.locals.session; const { data: order } = await database().from('orders').select('*').eq('order_number', req.params.publicId).eq('user_id', s.user_id).maybeSingle(); if (!order) return error(res, 404, 'ORDER_NOT_FOUND'); if (order.status === 'canceled') return res.json({ success: true, data: order, duplicated: true }); if (!['pending_payment', 'paid'].includes(order.status)) return error(res, 409, 'ORDER_NOT_CANCELLABLE'); await database().from('orders').update({ status: 'canceled' }).eq('id', order.id); const { data: items } = await database().from('order_items').select('*').eq('order_id', order.id); for (const item of (items || [])) { const { data: pv } = await database().from('product_variants').select('reserved').eq('id', item.variant_id).maybeSingle(); if (pv && (pv.reserved || 0) >= item.quantity) { await database().from('product_variants').update({ reserved: pv.reserved - item.quantity }).eq('id', item.variant_id); } } if (order.coupon_code) { const { data: cRow } = await database().from('coupons').select('reserved').eq('code', order.coupon_code).maybeSingle(); if (cRow && (cRow.reserved || 0) > 0) await database().from('coupons').update({ reserved: cRow.reserved - 1 }).eq('code', order.coupon_code); } await database().rpc('release_hold', { p_order_id: order.id }); /* claimedCancel: state-qualified */ const claimedCancel = await database().from('orders').update({ status: 'canceled' }).eq('id', order.id).in('status', ['pending_payment','paid']).select('id').maybeSingle(); await database().from('outbox').insert({ effect_key: `order-cancel:${order.id}`, kind: 'ORDER_CANCELED', payload: { order_id: order.id } }); await notificationService.sendCancellationNotification(order); res.json({ success: true, data: { ...order, status: 'canceled' } }); } catch { error(res, 503, 'ORDERS_UNAVAILABLE'); } });

// TOSS PAYMENTS (finding #1: fail-closed until live payments are enabled;
// only verified Toss results may move an order to paid)
app.post('/api/v1/payments/toss/prepare', authenticate, checkoutLimiter, async (req, res) => { try { if (env.PAYMENTS_ENABLED !== 'true') return error(res, 503, 'PAYMENTS_DISABLED'); const s = req.locals.session; const { orderId } = req.body; const { data: order } = await database().from('orders').select('*').eq('order_number', orderId).eq('user_id', s.user_id).maybeSingle(); if (!order) return error(res, 404, 'ORDER_NOT_FOUND'); if (!['pending_payment'].includes(order.status)) return error(res, 409, 'ORDER_STATE_INVALID'); res.json({ success: true, data: { orderId: order.order_number, amount: order.amount, clientKey: env.TOSS_CLIENT_KEY || '' } }); } catch { error(res, 503, 'PAYMENTS_UNAVAILABLE'); } });
app.post('/api/v1/payments/toss/confirm', authenticate, checkoutLimiter, async (req, res) => { try { if (env.PAYMENTS_ENABLED !== 'true') return error(res, 503, 'PAYMENTS_DISABLED'); const { paymentKey, orderId, amount } = req.body; const s = req.locals.session; if (!paymentKey || !orderId || !Number.isInteger(amount)) return error(res, 400, 'INVALID_PAYMENT'); const { data: order } = await database().from('orders').select('*').eq('order_number', orderId).eq('user_id', s.user_id).maybeSingle(); if (!order) return error(res, 404, 'ORDER_NOT_FOUND'); if (order.amount !== amount) return error(res, 400, 'AMOUNT_MISMATCH'); if (!['pending_payment', 'confirming'].includes(order.status)) return error(res, 409, 'ORDER_STATE_INVALID'); const { data: claimed } = await database().from('orders').update({ status: 'confirming' }).eq('id', order.id).in('status', ['pending_payment','confirming']).select('id').maybeSingle(); if (!claimed) return error(res, 409, 'ORDER_STATE_INVALID'); try { const tossRes = await fetch(`https://api.tosspayments.com/v1/payments/confirm`, { method: 'POST', headers: { Authorization: `Basic ${Buffer.from(`${env.TOSS_SECRET_KEY}:`).toString('base64')}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ paymentKey, orderId, amount }) }); const payment = await tossRes.json(); if (!tossRes.ok) throw payment; const method = String(payment.method || payment.easyPay?.provider || '').toUpperCase(); if (method !== 'CARD' && method !== '카드') { await database().from('orders').update({ status: 'pending_payment' }).eq('id', order.id); return error(res, 400, 'CARD_ONLY'); } const state_conflict = await database().from('orders').update({ status: 'paid' }).eq('id', order.id).eq('status', 'confirming').select('id').maybeSingle(); if (!state_conflict) return error(res, 409, 'payment.state_conflict'); await database().from('outbox').insert({ effect_key: `payment:${order.id}`, kind: 'PAYMENT_CONFIRMED', payload: { order_id: order.id, status: 'paid', paymentKey } }); await earnRewardPoints(order.user_id, order.id, order.amount); res.json({ success: true, data: { orderId: order.order_number, status: 'paid' } }); } catch (err) { await database().from('orders').update({ status: 'pending_payment' }).eq('id', order.id); throw err; } } catch { error(res, 503, 'PAYMENTS_UNAVAILABLE'); } });
app.post('/api/v1/payments/toss/webhook', async (req, res) => { try { res.sendStatus(200); const body = req.body; if (!body.orderId) return; const id = String(req.get('tosspayments-webhook-transmission-id') || `${body.orderId}:${body.status}`); const order = await database().from('orders').select('id,order_number').eq('order_number', body.orderId).maybeSingle(); if (!order) return; await database().from('webhook_events').insert({ id, order_number: body.orderId, order_id: order.id, status: body.status }).maybeSingle(); } catch { /* eslint-disable-line no-empty */ } });
app.post('/api/v1/admin/payments/:id/refunds', authenticate, staff(['super_admin', 'admin', 'order_manager']), stepUp, async (req, res) => { try { if (env.PAYMENTS_ENABLED !== 'true') return error(res, 503, 'PAYMENTS_DISABLED'); const idempotencyKey = String(req.get('Idempotency-Key') || ''); if (idempotencyKey && !/^[A-Za-z0-9._:-]{8,200}$/.test(idempotencyKey)) return error(res, 400, 'IDEMPOTENCY_KEY_REQUIRED'); const { data: payment } = await database().from('payments').select('*,orders(*)').eq('order_id', req.params.id).maybeSingle(); if (!payment?.payment_key) return error(res, 404, 'PAYMENT_NOT_FOUND'); try { const tossRes = await fetch(`https://api.tosspayments.com/v1/payments/${payment.payment_key}/cancel`, { method: 'POST', headers: { Authorization: `Basic ${Buffer.from(`${env.TOSS_SECRET_KEY}:`).toString('base64')}`, 'Content-Type': 'application/json' }, body: JSON.stringify({ cancelReason: req.body.reason }), 'Idempotency-Key': String(payment.cancel_key || req.body.reason) }); const result = await tossRes.json(); if (!tossRes.ok) throw result; if (payment.status === 'refunded') return res.json({ success: true, data: result, duplicated: true }); await database().from('payments').update({ status: 'refunded' }).eq('order_id', payment.order_id); await database().from('orders').update({ status: 'refunded' }).eq('id', payment.order_id); res.json({ success: true, data: result }); } catch (err) { error(res, 500, 'REFUND_FAILED'); } } catch { error(res, 503, 'PAYMENTS_UNAVAILABLE'); } });


// SHIPMENT / TRACKING
app.post('/api/v1/orders/:publicId/shipments', authenticate, staff(['super_admin','admin','order_manager']), stepUp, async (req, res) => { try { const s = req.locals.session; const { data: order } = await database().from('orders').select('*').eq('order_number', req.params.publicId).maybeSingle(); if (!order) return error(res, 404, 'ORDER_NOT_FOUND'); if (!['paid','processing'].includes(order.status)) return error(res, 409, 'ORDER_NOT_SHIPPABLE'); const { data: shipment } = await database().from('shipments').insert({ order_id: order.id, courier_name: req.body.courier || '', tracking_number: req.body.tracking_number || '', status: 'dispatched' }).select().maybeSingle(); await database().from('orders').update({ status: 'shipped' }).eq('id', order.id); await database().from('order_status_history').insert({ order_id: order.id, status: 'shipped', note: 'Shipment dispatched', actor_id: s.user_id }); await notificationService.sendShippingUpdate(order); res.json({ success: true, data: shipment }); } catch { error(res, 503, 'SHIPMENT_UNAVAILABLE'); } });
app.get('/api/v1/orders/:publicId/tracking', authenticate, async (req, res) => { try { const { data: order } = await database().from('orders').select('*').eq('order_number', req.params.publicId).eq('user_id', req.locals.session.user_id).maybeSingle(); if (!order) return error(res, 404, 'ORDER_NOT_FOUND'); const { data: events } = await database().from('order_status_history').select('*').eq('order_id', order.id).order('created_at', { ascending: false }); res.json({ success: true, data: { order, events } }); } catch { error(res, 503, 'TRACKING_UNAVAILABLE'); } });

// REVIEW WRITE
app.post('/api/v1/products/:id/reviews', checkoutLimiter, authenticate, async (req, res) => { try { const s = req.locals.session; const { rating, comment } = req.body || {}; if (!rating || rating < 1 || rating > 5) return error(res, 400, 'INVALID_RATING'); const { data, error: e } = await database().from('reviews').insert({ product_id: req.params.id, user_id: s.user_id, rating: Number(rating), comment: String(comment || '').slice(0, 500), is_approved: false }).select().maybeSingle(); if (e || !data) throw e || new Error('REVIEW_CREATE_FAILED'); res.status(201).json({ success: true, data }); } catch { error(res, 503, 'REVIEWS_UNAVAILABLE'); } });

// REVIEW MODERATION
app.post('/api/v1/reviews/:id/moderate', authenticate, staff(['super_admin','admin']), async (req, res) => { try { const { data: review } = await database().from('reviews').select('*').eq('id', req.params.id).maybeSingle(); if (!review) return error(res, 404, 'REVIEW_NOT_FOUND'); const { is_approved } = req.body; await database().from('reviews').update({ is_approved, moderated_by: req.locals.session.user_id, moderated_at: new Date().toISOString() }).eq('id', req.params.id); await auditLog(req, 'REVIEW_MODERATE', { table: 'reviews', id: req.params.id }); res.json({ success: true }); } catch { error(res, 503, 'MODERATION_UNAVAILABLE'); } });

// PRIVACY REQUESTS
app.post('/api/v1/me/privacy-request', authenticate, privacyLimiter, async (req, res) => { try { const s = req.locals.session; const validTypes = ['export','delete','correct']; if (!validTypes.includes(req.body.type)) return error(res, 400, 'INVALID_PRIVACY_TYPE'); const kind = req.body.type; const { data: privacy } = await database().from('privacy_requests').insert({ user_id: s.user_id, kind, status: 'pending' }).select().maybeSingle(); await notificationService.sendInquiryResponse({ id: privacy.id, customer_email: s.profiles.email, category: 'privacy', response: 'Your request has been received and is being processed.' }); res.json({ success: true, data: privacy }); } catch { error(res, 503, 'PRIVACY_UNAVAILABLE'); } });
app.get('/api/v1/admin/privacy-requests', authenticate, staff(['super_admin','admin']), async (req, res) => { try { const { data } = await database().from('privacy_requests').select('*').order('created_at', { ascending: false }).limit(100); res.json({ success: true, data: data || [] }); } catch { error(res, 503, 'PRIVACY_UNAVAILABLE'); } });

// AUDIT LOGS
app.get('/api/v1/admin/audit-logs', authenticate, staff(['super_admin','admin']), async (req, res) => { try { const { data } = await database().from('audit_logs').select('*').order('created_at', { ascending: false }).limit(200); res.json({ success: true, data: data || [] }); } catch { error(res, 503, 'AUDIT_UNAVAILABLE'); } });

// ERROR HANDLER
app.use((err, req, res, next) => { /* eslint-disable-line no-unused-vars */ console.error(err); if (!res.headersSent) error(res, 500, 'INTERNAL_ERROR'); });

const port = Number(env.PORT || 5001);
export default app;
export const router = app;
if (process.argv[1] === new URL(import.meta.url).pathname) { app.listen(port, () => { console.log(`NOEUL production API listening on ${port}`); if (process.env.WORKERS_ENABLED !== '0') { startOutboxWorker().catch(err => console.error('[Outbox] start failed:', err.message)); startExpiryWorker().catch(err => console.error('[Expiry] start failed:', err.message)); } }); }
